// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    HelperReceiver r;

    function setUp() public { 
        c = new C();
        r = new HelperReceiver();
    }

    // fuzz the from address, a single recipient in the array, and a value
    function testFuzz_property(address from, uint256 v) public {
        // admissible domain: _tos must be non-empty; we provide one recipient (the helper)
        // also avoid the zero address for 'from' to keep it wide but sensible
        vm.assume(from != address(0));

        address[] memory tos = new address[](1);
        tos[0] = address(r);

        // call transfer and capture whether it returns true or false (without reverting)
        bool ok;
        try c.transfer(from, address(r), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // should not revert in either reference or mutant for this scenario (helper succeeds)
            ok = false;
        }

        // General rule: reference implementation always returns true for any non-empty tos when calls succeed.
        // We assert that the observed return value is true. The mutant (which returns false) will make this fail
        // for some inputs (the fuzzer will find them).
        assertTrue(ok);
    }
}

// Minimal helper that accepts the low-level call and returns as expected
contract HelperReceiver {
    // match the signature transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // fallback to accept any low-level call
    fallback() external payable {
    }
}
